#!/usr/bin/env bun
// Generates src/spdx-ids.ts from the spdx-license-ids package.
// Run when bumping spdx-license-ids or once at setup time.
// The generated file is committed; this script is for regeneration only.

import spdxIds from 'spdx-license-ids';
import deprecatedIds from 'spdx-license-ids/deprecated.json' with { type: 'json' };
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const all = [...new Set([...spdxIds, ...deprecatedIds])].sort();

const content = `// AUTO-GENERATED by scripts/gen-spdx-ids.ts. Do not edit by hand.
// Run \`bun run scripts/gen-spdx-ids.ts\` to regenerate from spdx-license-ids.

export const SPDX_IDS: ReadonlySet<string> = new Set([
${all.map((id) => `  ${JSON.stringify(id)},`).join('\n')}
]);
`;

writeFileSync(
  resolve(import.meta.dir, '..', 'src', 'spdx-ids.ts'),
  content,
);

console.log(`Wrote ${all.length} SPDX IDs to src/spdx-ids.ts`);
